create or replace function public.player_memory_v2(p_player_id bigint,p_competition text default null) returns jsonb language sql stable security invoker set search_path=public as $$ with base as(select gps.*,g.game_date,row_number()over(order by g.game_date desc nulls last,gps.game_id desc)rn,coalesce((gps.stats->>'points')::numeric,0)pts,coalesce((gps.stats->>'rebounds')::numeric,(gps.stats->>'reb')::numeric,0)reb,coalesce((gps.stats->>'ast')::numeric,(gps.stats->>'assists')::numeric,0)ast,coalesce((gps.stats->>'tov')::numeric,(gps.stats->>'turnovers')::numeric,0)tov,coalesce((gps.stats->>'three_pa')::numeric,0)three_pa,coalesce((gps.calculated->>'ts')::numeric,0)ts,coalesce((gps.calculated->>'efg')::numeric,0)efg from public.game_player_stats gps join public.games g on g.id=gps.game_id where gps.player_id=p_player_id and gps.verified=true and(p_competition is null or gps.competition=p_competition)),agg as(select count(*)games,coalesce(sum(minutes),0)mins,avg(minutes)mpg,avg(pts)ppg,avg(reb)rpg,avg(ast)apg,avg(tov)tovpg,avg(ts)ts,avg(efg)efg,avg(three_pa)three_pa,avg(minutes)filter(where rn<=5)l5_mpg,avg(pts)filter(where rn<=5)l5_ppg,avg(ts)filter(where rn<=5)l5_ts,avg(three_pa)filter(where rn<=5)l5_three_pa,avg(minutes)filter(where rn>5)prev_mpg,avg(pts)filter(where rn>5)prev_ppg from base),flags as(select *,case when games<3 or mins<40 then 'SMALL_SAMPLE' when games>=6 and abs(coalesce(l5_mpg,0)-coalesce(prev_mpg,0))>=5 then 'ROLE_CHANGE' when games>=6 and abs(coalesce(l5_ppg,0)-coalesce(prev_ppg,0))>=4 then 'TREND' else 'STABLE' end primary_flag from agg)select jsonb_build_object('player_id',p_player_id,'competition',p_competition,'summary',jsonb_build_object('games',games,'minutes',round(mins,1),'mpg',round(mpg,1),'ppg',round(ppg,1),'rpg',round(rpg,1),'apg',round(apg,1),'tovpg',round(tovpg,1),'ts',round(ts,1),'efg',round(efg,1),'three_pa',round(three_pa,1)),'last5',jsonb_build_object('mpg',round(l5_mpg,1),'ppg',round(l5_ppg,1),'ts',round(l5_ts,1),'three_pa',round(l5_three_pa,1)),'flag',primary_flag,'confidence',case when games>=10 then .9 when games>=6 then .75 when games>=3 then .55 else .25 end,'game_log',(select coalesce(jsonb_agg(jsonb_build_object('game_id',game_id,'date',game_date,'team',team_name,'opponent',opponent_name,'minutes',minutes,'points',pts,'rebounds',reb,'assists',ast,'turnovers',tov,'ts',ts,'efg',efg,'three_pa',three_pa)order by game_date desc nulls last,game_id desc),'[]'::jsonb)from base))from flags;$$;revoke all on function public.player_memory_v2(bigint,text) from public,anon;grant execute on function public.player_memory_v2(bigint,text) to authenticated;